module top(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] A,\n    input wire [31:0] B,\n    input wire [6:0] S,\n    output reg [15:0] count,\n    output reg [31:0] candidate,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] CALC_A_MINUS = 4'd1;\n    localparam [3:0] DP_INIT_B    = 4'd2;\n    localparam [3:0] DP_PROCESS_B = 4'd3;\n    localparam [3:0] DP_INIT_A    = 4'd4;\n    localparam [3:0] DP_PROCESS_A = 4'd5;\n    localparam [3:0] FIND_MIN     = 4'd6;\n    localparam [3:0] FINISH       = 4'd7;\n\n    // Internal registers\n    reg [3:0] state, next_state;\n    reg [7:0] cycle_counter;\n    reg [31:0] dp_current [0:1][0:1][0:72];\n    reg [31:0] dp_next [0:1][0:1][0:72];\n    reg [7:0] digit_pos;\n    reg [31:0] A_reg;\n    reg [31:0] B_reg;\n    reg [6:0] S_reg;\n    reg [31:0] count_B;\n    reg [31:0] count_A1;\n    reg [3:0] a_minus1 [7:0];\n    reg [3:0] a_digits [7:0];\n    reg [3:0] b_digits [7:0];\n    reg [1:0] tight_l, tight_u;\n    reg [6:0] current_sum;\n    reg [7:0] pos;\n\n    integer i, j, k, sum, dig;\n\n    // Constants\n    localparam MAX_CYCLES = 8'd200;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            count <= 16'd0;\n            candidate <= 32'd0;\n            done <= 1'b0;\n            cycle_counter <= 8'd0;\n            for (i = 0; i < 72; i = i + 1) begin\n                for (j = 0; j < 2; j = j +1) begin\n                    for (k = 0; k < 2; k = k +1) begin\n                        dp_current[j][k][i] <= 16'd0;\n                        dp_next[j][k][i] <= 16'd0;\n                    end\n                end\n            end\n            pos <= 8'd0;\n        end else begin\n            cycle_counter <= (state == IDLE) ? 8'd0 : cycle_counter + 8'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        A_reg <= A;\n                        B_reg <= B;\n                        S_reg <= S;\n                        next_state <= CALC_A_MINUS;\n                    end\n                end\n\n                CALC_A_MINUS: begin\n                    // A_minus1 logic\n                    // Extract digits from A_reg into a_digits\n                    for (i = 0; i < 8; i = i +1) begin\n                        a_digits[i] <= (A_reg >> (4*i)) & 4'd15;\n                        b_digits[i] <= (B_reg >> (4*i)) & 4'd15;\n                    end\n\n                    // Subtraction logic (A-1)\n                    a_minus1[0] <= (a_digits[0] != 4'd0) ? a_digits[0] - 4'd1 : 4'd9;\n                    for (i = 1; i < 8; i = i +1) \n                        a_minus1[i] <= (a_digits[i] > 4'd0 || |a_digits[i-1:0]) ? a_digits[i] : 4'd9;\n\n                    next_state <= DP_INIT_B;\n                end\n\n                DP_INIT_B: begin\n                    for (i = 0; i < 72; i = i +1) begin\n                        dp_current[1][1][i] <= 32'd0;\n                        dp_current[1][0][i] <= 32'd0;\n                        dp_current[0][1][i] <= 32'd0;\n                        dp_current[0][0][i] <= 32'd0;\n                    end\n                    dp_current[1][1][0] <= 32'd1;\n                    digit_pos <= 8'd7;\n                    next_state <= DP_PROCESS_B;\n                end\n\n                DP_PROCESS_B: begin\n                    for (tight_l = 0; tight_l < 2; tight_l = tight_l + 1) begin\n                        for (tight_u = 0; tight_u < 2; tight_u = tight_u + 1) begin\n                            for (sum = 0; sum < 73; sum = sum + 1) begin\n                                if (dp_current[tight_l][tight_u][sum] > 0) begin\n                                    for (dig = 0; dig < 10; dig = dig + 1) begin\n                                        if ((tight_l ? dig >= a_digits[digit_pos] : 1) && \n                                            (tight_u ? dig <= b_digits[digit_pos] : 1)) begin\n                                            dp_next[tight_l & (dig == a_digits[digit_pos])][tight_u & (dig == b_digits[digit_pos])][sum + dig] <= \n                                                dp_next[tight_l & (dig == a_digits[digit_pos])][tight_u & (dig == b_digits[digit_pos])][sum + dig] + \n                                                dp_current[tight_l][tight_u][sum];\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n\n                    if (digit_pos == 0) begin\n                        next_state <= DP_INIT_A;\n                    end else begin\n                        digit_pos <= digit_pos - 1;\n                        // Swap dp_current and dp_next\n                        for (tight_l = 0; tight_l < 2; tight_l = tight_l + 1) \n                            for (tight_u = 0; tight_u < 2; tight_u = tight_u + 1) \n                                for (sum = 0; sum < 73; sum = sum + 1) begin\n                                    dp_current[tight_l][tight_u][sum] <= dp_next[tight_l][tight_u][sum];\n                                    dp_next[tight_l][tight_u][sum] <= 32'd0;\n                                end\n                    end\n                end\n\n                DP_INIT_A: begin\n                    // Similar initialization as DP_INIT_B but for A_minus\n                    // ... (implementation similar to DP_INIT_B with A_minus1 instead of B)\n                    next_state <= DP_PROCESS_A;\n                end\n\n                DP_PROCESS_A: begin\n                    // Similar processing as DP_PROCESS_B for A_minus1\n                    // ...\n                    next_state <= FIND_MIN;\n                end\n\n                FIND_MIN: begin\n                    // Greedy search for smallest valid candidate\n                    // ...\n                    count <= (count_B - count_A1) > 16'd65535 ? 16'd65535 : (count_B - count_A1);\n                    next_state <= FINISH;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n\n            // Timeout guard\n            if (cycle_counter >= MAX_CYCLES) begin\n                state <= IDLE;\n                done <= 1'b0;\n            end\n        end\n    end\nendmodule